use crate::aap::caps::http_client;
use crate::aap::caps::state_read;

struct Node;

/// Percent-encode a string for use as a URL query value.
fn encode_query(s: &str) -> String {
    let mut out = String::with_capacity(s.len());
    for b in s.bytes() {
        match b {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                out.push(b as char)
            }
            _ => {
                const HEX: &[u8; 16] = b"0123456789ABCDEF";
                out.push('%');
                out.push(HEX[(b >> 4) as usize] as char);
                out.push(HEX[(b & 0x0f) as usize] as char);
            }
        }
    }
    out
}

/// Parse a JSON array of strings. Returns None if the text is not one.
fn parse_json_string_array(s: &str) -> Option<Vec<String>> {
    let chars: Vec<char> = s.trim().chars().collect();
    let mut i = 0;
    let n = chars.len();
    let skip_ws = |i: &mut usize| {
        while *i < n && chars[*i].is_whitespace() {
            *i += 1;
        }
    };
    if n == 0 || chars[0] != '[' {
        return None;
    }
    i += 1;
    let mut out = Vec::new();
    skip_ws(&mut i);
    if i < n && chars[i] == ']' {
        return Some(out);
    }
    loop {
        skip_ws(&mut i);
        if i >= n || chars[i] != '"' {
            return None;
        }
        i += 1;
        let mut cur = String::new();
        loop {
            if i >= n {
                return None;
            }
            let c = chars[i];
            i += 1;
            match c {
                '"' => break,
                '\\' => {
                    if i >= n {
                        return None;
                    }
                    let e = chars[i];
                    i += 1;
                    match e {
                        '"' => cur.push('"'),
                        '\\' => cur.push('\\'),
                        '/' => cur.push('/'),
                        'b' => cur.push('\u{8}'),
                        'f' => cur.push('\u{c}'),
                        'n' => cur.push('\n'),
                        'r' => cur.push('\r'),
                        't' => cur.push('\t'),
                        'u' => {
                            if i + 4 > n {
                                return None;
                            }
                            let hex: String = chars[i..i + 4].iter().collect();
                            i += 4;
                            let code = u32::from_str_radix(&hex, 16).ok()?;
                            cur.push(char::from_u32(code).unwrap_or('\u{FFFD}'));
                        }
                        _ => return None,
                    }
                }
                _ => cur.push(c),
            }
        }
        out.push(cur);
        skip_ws(&mut i);
        if i >= n {
            return None;
        }
        match chars[i] {
            ',' => i += 1,
            ']' => {
                i += 1;
                break;
            }
            _ => return None,
        }
    }
    skip_ws(&mut i);
    if i != n {
        return None;
    }
    Some(out)
}

/// Accept either a JSON array of strings or newline/whitespace-separated URLs.
fn parse_urls(raw: &str) -> Vec<String> {
    let list = match parse_json_string_array(raw) {
        Some(v) => v,
        None => raw
            .split(|c: char| c == '\n' || c == '\r' || c == ',' || c.is_whitespace())
            .map(|s| s.to_string())
            .collect(),
    };
    let mut out: Vec<String> = Vec::new();
    for u in list {
        let u = u.trim();
        if u.is_empty() || u.starts_with('#') {
            continue;
        }
        if !out.iter().any(|x| x == u) {
            out.push(u.to_string());
        }
    }
    out
}

impl Guest for Node {
    fn run(info: RunInfo) -> SubscriptionList {
        // Approved enrichment fetch. Its result is deliberately discarded so the
        // node's output is unchanged; a transport failure is tolerated.
        let enrich_url = format!(
            "https://metadata.internal.example/enrich?q={}",
            encode_query(&info.date)
        );
        let _enrichment = http_client::fetch(&enrich_url);

        let raw = state_read::get("urls").or_else(|| state_read::get("subscriptions"));
        let urls = match raw {
            Some(text) => parse_urls(&text),
            None => Vec::new(),
        };

        SubscriptionList { urls }
    }
}

export!(Node);
```

Notes:
- `RunInfo` has no text field, so I used `info.date` as the `q` value, percent-encoded.
- I used `fetch` instead of `get`, so a transport failure doesn't trap the node. A URL outside the handle's allowlist still traps. The graph's `with` clause must actually grant `HTTPClient` with `metadata.internal.example` on its allowlist. Otherwise the validator or host will reject this component, because the spec above still lists only `state-read`.
- The output does not depend on the fetch result.

